#include <stdio.h>
/*
 * ex06：三种装入方式下的地址计算
 *   绝对装入     ：编译时就按「程序一定装在 0x0000」定死地址，换位置就崩
 *   可重定位装入 ：装入时一次性把所有地址加上「装入地址」，之后不能再移动
 *   动态运行时装入：地址在运行时由「重定位寄存器 + 逻辑地址」现算，可随时移动
 * 本程序把同一段程序放到两个不同的装入地址上，看三种方式的结果。
 */
#define LOAD1 0x1000
#define LOAD2 0x3000

int main(void) {
    /* 程序里的逻辑地址（编译期确定） */
    unsigned logical[] = {0x0000, 0x0010, 0x0040, 0x0100};
    const char *what[] = {"main 入口", "全局变量 g", "字符串常量", "函数 foo"};
    int n = 4;

    printf("装入地址 A = 0x%04X\n", LOAD1);
    printf("%-14s %-8s %-10s %-10s %s\n", "对象", "逻辑地址", "绝对装入", "静态重定位", "动态重定位");
    for (int i = 0; i < n; i++) {
        printf("%-14s 0x%04X   0x%04X     0x%04X     0x%04X\n",
               what[i], logical[i], logical[i], logical[i] + LOAD1, logical[i] + LOAD1);
    }

    printf("\n把同一个进程换到装入地址 B = 0x%04X（例如被换出后又换入到别处）\n", LOAD2);
    printf("%-14s %-10s %-12s %s\n", "对象", "静态重定位", "动态重定位", "说明");
    for (int i = 0; i < n; i++) {
        unsigned stat = logical[i] + LOAD1;   /* 静态重定位的表项已经写死了，不会变 */
        unsigned dyn = logical[i] + LOAD2;    /* 动态只要改重定位寄存器 */
        printf("%-14s 0x%04X      0x%04X       静态已失效 / 动态正确\n", what[i], stat, dyn);
    }
    printf("\n结论：静态重定位「装完就锁死」，所以不支持换出换入；\n");
    printf("      动态运行时装入靠一个寄存器兜底，才让「虚拟内存 + 进程迁移」成为可能。\n");
    return 0;
}
